function queueChunk(cx,cz){if(Math.abs(cx-Math.floor(player.x/CHUNK))<=radius&&Math.abs(cz-Math.floor(player.z/CHUNK))<=radius)pending.set(`${cx},${cz}`,[cx,cz])}
function dirty(x,z){const cx=Math.floor(x/CHUNK),cz=Math.floor(z/CHUNK);queueChunk(cx,cz);if(((x%16)+16)%16===0)queueChunk(cx-1,cz);if(((x%16)+16)%16===15)queueChunk(cx+1,cz);if(((z%16)+16)%16===0)queueChunk(cx,cz-1);if(((z%16)+16)%16===15)queueChunk(cx,cz+1)}
function updateChunks(){const cx=Math.floor(player.x/CHUNK),cz=Math.floor(player.z/CHUNK),id=`${cx},${cz},${radius}`;if(lastCenter===id)return;lastCenter=id;for(const [k,m]of chunks){const [x,z]=k.split(',').map(Number);if(Math.abs(x-cx)>radius||Math.abs(z-cz)>radius){scene.remove(m);m.geometry.dispose();chunks.delete(k)}}for(const [k,[x,z]]of pending)if(Math.abs(x-cx)>radius||Math.abs(z-cz)>radius)pending.delete(k);for(let r=0;r<=radius;r++)for(let dx=-r;dx<=r;dx++)for(let dz=-r;dz<=r;dz++)if(Math.max(Math.abs(dx),Math.abs(dz))===r&&!chunks.has(`${cx+dx},${cz+dz}`))queueChunk(cx+dx,cz+dz)}
