  // ne doit pas dépendre de l'image où la gravité détecte la collision.
  if(!player.ground&&player.vy<=0&&collide(player.x,player.y-.055,player.z)){player.y=Math.floor(player.y-.055)+1;player.vy=0;player.ground=true}
  if(player.y < -12){hurt(50);resetPlayer()}
