function truckPassageClear(p){const yaw=headingTo(p.dx,p.dz),c=Math.cos(yaw),s=Math.sin(yaw);for(const lx of [-1.4,0,1.4])for(const lz of [-4.2,-1,2,5.9]){const x=Math.floor(p.x+c*lx+s*lz),z=Math.floor(p.z-s*lx+c*lz);for(let y=8;y<12;y++)if(world.get(x,y,z))return false}return true}
