function summon(){if(!kitt.visible){const p=isInsideBistro(player.x,player.z)?{x:-17.5,z:-3}:player,candidates=[];for(const r of [6,10,14])for(let i=0;i<16;i++){const a=i*Math.PI/8,x=p.x+Math.cos(a)*r,z=p.z+Math.sin(a)*r,y=heightAt(x,z)+1;if(column(x,z).road&&!collide(x,y+.05,z,1,1.6))candidates.push({x,y,z})}const spot=candidates.sort((a,b)=>Math.hypot(a.x-p.x,a.z-p.z)-Math.hypot(b.x-p.x,b.z-p.z))[0];if(spot)Object.assign(vehicle,{...spot,vy:0,speed:0,yaw:headingTo(p.x-spot.x,p.z-spot.z)});else if(Math.hypot(vehicle.x-p.x,vehicle.z-p.z)>30){for(const r of [6,10]){const x=p.x+r,z=p.z,y=heightAt(x,z)+1;if(!collide(x,y+.05,z,1,1.6)){Object.assign(vehicle,{x,y,z,vy:0,speed:0,yaw:headingTo(p.x-x,p.z-z)});break}}}}kitt.visible=true;vehicle.auto=true;say(isInsideBistro(player.x,player.z)?'Je vous attends devant le bar. Le comptoir est déjà suffisamment encombré.':'Je vous rejoins par la route, une fois. Évitez de construire un mur entre nous.')}
