  if(driving){const gas=Number(down('forward'))-Number(down('back')),oldSpeed=vehicle.speed,steering=Number(down('left'))-Number(down('right'));vehicle.speed=THREE.MathUtils.damp(vehicle.speed,gas*(gas<0?6:17+campaign.engine*3),gas?(patrol?.effects().acceleration||1.6):3,dt);vehicle.braking=Math.abs(oldSpeed)>2&&(gas===0||Math.sign(gas)!==Math.sign(oldSpeed))&&Math.abs(vehicle.speed)<Math.abs(oldSpeed)-.03;vehicle.yaw+=steering*dt*1.55*Math.min(1,Math.abs(vehicle.speed)/3);vehicle.skidding=Math.abs(vehicle.speed)>(patrol?.effects().skidThreshold||9)&&Math.abs(steering)>0}
