function roomList(list){$('roomList').replaceChildren();$('publicRooms').replaceChildren();for(const r of list){const o=document.createElement('option');o.value=r.id;$('publicRooms').append(o);const b=document.createElement('button');b.textContent=`${r.id} · ${r.players}/${r.capacity}`;b.onclick=()=>$('roomCode').value=r.id;$('roomList').append(b)}}
function setRemote(p){if(!p||p.id===socket?.id)return;let r=remotes.get(p.id);if(!r){const group=new THREE.Group(),body=avatar(p.profile||'MICHAEL'),vehicle=car(true);if(p.name)body.add(nameLabel(p.name));group.add(body,vehicle);scene.add(group);r={group,body,vehicle,name:p.name||'',target:new THREE.Vector3(p.x,p.y,p.z),yaw:p.yaw||0,moving:0};group.position.copy(r.target);remotes.set(p.id,r)}if(Number.isFinite(p.x)){r.moving=Math.min(1,r.target.distanceTo(new THREE.Vector3(p.x,p.y,p.z))*2);r.target.set(p.x,p.y,p.z)}r.yaw=p.yaw||0;r.body.visible=!p.driving;r.vehicle.visible=!!p.driving}
function initSocket(){if(socket)return socket;if(!window.io){$('networkStatus').textContent='Service multijoueur indisponible. Le mode solo reste disponible.';return null}socket=window.io({path:new URL('./socket.io',location.href).pathname,autoConnect:true,reconnection:true});socket.on('room:list',roomList);socket.on('player:joined',setRemote);socket.on('player:state',setRemote);socket.on('player:left',id=>{const r=remotes.get(id);if(r){scene.remove(r.group);remotes.delete(id)}});socket.on('world:block',localEdit);socket.on('connect_error',()=>$('networkStatus').textContent='Serveur inaccessible. Le mode solo reste disponible.');socket.on('disconnect',()=>{if(gameMode==='online'){$('netBadge').textContent='RECONNEXION…';toast('Connexion perdue. Les modifications sont suspendues.')}});socket.on('connect',async()=>{socket.emit('room:list');$('networkStatus').textContent='Serveur disponible · 16 places par salle';if(gameMode==='online'&&joinInfo){try{if(adminToken){const r=await ack('profile:resume',{token:adminToken});if(!r.ok){adminProfile=null;adminToken=null;toast('Session privée expirée. Le profil pilote est utilisé.')}}await enterRoom(joinInfo,true)}catch{toast('Reconnexion à la salle impossible. Ouvrez le menu.')}}});return socket}
function connected(){if(!initSocket())return Promise.reject(new Error('Service multijoueur indisponible. Le mode solo reste disponible.'));if(socket.connected)return Promise.resolve();return new Promise((resolve,reject)=>{const timer=setTimeout(()=>{socket.off('connect',done);reject(new Error('Connexion expirée'))},7000);const done=()=>{clearTimeout(timer);resolve()};socket.once('connect',done)})}
const ack=(event,data)=>socket.timeout(7000).emitWithAck(event,data);
function leaveNetwork(){joinInfo=null;if(socket?.connected)socket.emit('room:leave');gameMode='solo';netRoom='';clearRemotes()}
async function enterRoom(info,reconnect=false){const r=await ack('room:join',info);if(!r.ok)throw new Error(r.error);gameMode='online';joinInfo=info;save('kitt.room.v1',info);netRoom=r.room;clearRemotes();world.snapshot(r.blocks);refreshWorld();for(const p of r.players)setRemote(p);resetPlayer();const self=r.players.find(p=>p.id===socket.id);if(self)Object.assign(player,{x:self.x,y:self.y,z:self.z});driving=false;mode=adminProfile?'creative':'survival';renderBar();if(!reconnect)start();$('networkStatus').textContent=`${r.room} · ${r.players.length}/16 pilotes`;say(reconnect?'Connexion rétablie. Retour au poste FLAG, monde resynchronisé.':'Bienvenue sur le réseau FLAG. Construisez ensemble.')}
$('joinBtn').onclick=async()=>{if(!await unlock())return;const b=$('joinBtn');b.disabled=true;try{await connected();const privateRoom=$('privateRoom').checked;if(privateRoom&&!$('roomCode').value.startsWith('PRIVE-'))$('roomCode').value='PRIVE-'+Array.from(crypto.getRandomValues(new Uint8Array(8)),v=>v.toString(16).padStart(2,'0')).join('').toUpperCase();await enterRoom({room:$('roomCode').value,name:adminProfile?PROFILES[adminProfile].name:pilotName(),anonymous:freeMode&&!pilotName(),profile:selectedProfile})}catch(e){$('networkStatus').textContent=e.message||'Impossible de rejoindre le serveur.'}finally{b.disabled=false}};
$('refreshRooms').onclick=async()=>{try{await connected();socket.emit('room:list')}catch{$('networkStatus').textContent='Serveur inaccessible.'}};
function sendPosition(){if(socket?.connected&&gameMode==='online')socket.volatile.emit('player:state',{x:player.x,y:player.y,z:player.z,yaw:driving?vehicle.yaw:player.yaw,driving})}

let heldBreak=false,lastBreakAt=0,breakBusy=false;async function mine(){if(breakBusy)return;firstPersonArms.setWeapon('');firstPersonArms.trigger('mine');breakBusy=true;try{await breakBlock()}finally{breakBusy=false}}
function clearInput(){pressed.clear();touch.clear();heldBreak=false}
function lockPointer(){if(coarse)return;awaitingPointer=document.pointerLockElement!==renderer.domElement;show('pointerPrompt',awaitingPointer);try{renderer.domElement.requestPointerLock?.()?.catch?.(()=>{if(!paused)show('pointerPrompt')})}catch{if(!paused)show('pointerPrompt')}}
function start(){const first=!started;started=true;paused=false;show('menu',false);show('hud');show('mobile');show('resumeBtn',Boolean(read('kitt.session.v1',null)||read('kitt.room.v1',null)));clearInput();renderBar();updateHints();sound.unlock();if(!coarse)lockPointer();sound.play(first?'start':'click');if(first)say(greet('bienvenue à FLAG. Le bouton PATROUILLES donne accès aux interventions de Bonnie et d’April. Devon propose aussi le sauvetage de Bonnie.'));refreshGuestLocks()}
async function solo(nextMode,resume=false){if(!await unlock())return;leaveNetwork();mode=nextMode;world.snapshot(read('kitt.world.v2',[]));refreshWorld();if(resume){const slot=read('kitt.session.v1',null);if(slot){Object.assign(player,slot.player);health=slot.health;hunger=slot.hunger}}else{resetPlayer();health=100;hunger=100}start()}
