async function resume(){const room=read('kitt.room.v1',null);if(room){if(!await unlock())return;try{await connected();await enterRoom(room);return}catch(e){toast('Reprise du salon impossible : '+e.message)}}const slot=read('kitt.session.v1',null);if(slot)await solo(slot.mode||'survival',true);else toast('Aucune partie sauvegardée.')}
