function populateVoiceSelectors(){if(!narrator.available)return;$('voiceMale').replaceChildren(new Option('Automatique · voix du navigateur',''));$('voiceFemale').replaceChildren(new Option('Automatique · voix du navigateur',''));const voices=speechSynthesis.getVoices().filter(v=>/^fr(?:-|$)/i.test(v.lang)).sort((a,b)=>a.lang.localeCompare(b.lang)||a.name.localeCompare(b.name));for(const v of voices){const label=`${v.name} · ${v.lang}${v.localService?' · appareil':' · réseau'}`;for(const id of ['voiceMale','voiceFemale'])$(id).add(new Option(label,v.voiceURI||v.name))} $('voiceMale').value=settings.voiceMale;$('voiceFemale').value=settings.voiceFemale;$('voiceStatus').textContent=voices.length?`${voices.length} voix françaises détectées sur cet appareil. Le choix automatique adapte la voix au personnage.`:'Aucune voix française détectée ; installe ou active des voix françaises dans les réglages du navigateur ou du système.'}
