for(const id of ['quality','viewDistance','mapBudget','volume','sensitivity','musicVolume','effectsVolume','halloween','voice','weather']){$(id).value=id==='halloween'||id==='voice'?settings[id]?'on':'off':id==='weather'?settings.weather?'rain':'clear':settings[id];$(id).oninput=()=>{settings[id]=id==='halloween'||id==='voice'?$(id).value==='on':id==='weather'?$(id).value==='rain':id==='quality'||id==='mapBudget'?$(id).value:Number($(id).value);save('kitt.settings.v2',settings);if(id==='quality'){const next=settings.quality==='auto'?autoQualityStart:settings.quality;adaptiveQuality.reset(next,performance.now());lastAutoFps=null}if(['quality','viewDistance','mapBudget'].includes(id))quality();mixSettings();creatures.update(playedTime,settings.halloween,null,undefined,0)}}
