function talkMichael(){if(Math.hypot(player.x-5,player.z+2)<4){if(!campaign.path){$('dialogChoices').classList.remove('hidden');say(greet('deux urgences à FLAG. On protège les moutons ou on enquête sur les démons ?'),PROFILES[selectedProfile]?.name||'KITT')}else say(greet('Michael est au hangar. Devon a la mission principale pour vous.'),'MICHAEL KNIGHT');return}const nearby=creatures.nearest(new THREE.Vector3(player.x,player.y,player.z));if(nearby){sound.play(nearby.type);if(nearby.type==='sheep'){sound.play('pet');say(greet('le mouton vous salue. La Fondation a visiblement recruté une tondeuse écologique.'),PROFILES[selectedProfile]?.name||'KITT')}else say(BESTIARY[nearby.type].name+' : une drôle de rencontre pour Halloween !');return}toast('E : parler près d’un membre de FLAG ou monter dans KITT. '+pretty(binds.follow)+' : appeler KITT.')}
