 firstPersonArms.trigger('use');
 if(bistro.nearPortrait(player)){sound.play('click');say(greet('C’est un cadeau de Cédric Momo Rider, qui aime les Belges, offert à Manix le Gaulois belge et architecte de ce monde.'),'MARCEL');return}
 if(flagTruckBoarded){if(!flagTruckBriefed){flagTruckBriefed=true;say(greet('Devon a la radio : rapport recu. Rassemble deux noyaux de rechange, appelez KITT et amenez-le pres de l atelier.'),'DEVON MILES');return}flagTruckBoarded=false;flagTruckBriefed=false;player.x=flagTruck.position.x+2.1;player.z=flagTruck.position.z;player.y=heightAt(player.x,player.z)+1;player.vy=0;if(campaign.flagTruckStage===1){campaign.flagTruckStage=2;save('kitt.campaign.v1',campaign);say(greet('Briefing recu. Trouve deux noyaux puis amene KITT pres de l atelier.'),'DEVON MILES')}else say(greet('Vous descendez du camion atelier.'));return}
